import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        p = [0] * (n + 1)
        for i in range(1, n + 1):
            p[i] = int(next(iterator))
    except StopIteration:
        return

    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            curr = i
            while not visited[curr]:
                visited[curr] = True
                cycle.append(curr)
                curr = p[curr]
            cycles.append(cycle)

    q = [0] * (n + 1)
    cycle_idx = 0
    cycle_len_idx = 0

    while cycle_idx < len(cycles):
        cycle = cycles[cycle_idx]
        L = len(cycle)
        cycle_idx += 1

        if L % 2 == 1:
            # Odd length cycle: shift by (L+1)//2
            shift = (L + 1) // 2
            for i in range(L):
                u = cycle[i]
                v = cycle[(i + shift) % L]
                q[u] = v
        else:
            # Even length cycle: need to pair with another cycle of same length
            if cycle_len_idx >= len(cycles):
                print("-1")
                return

            other_cycle = cycles[cycle_len_idx]
            if len(other_cycle) != L:
                print("-1")
                return
            cycle_len_idx += 1

            # Merge two even cycles into one structure for q
            # Let cycle A = [a0, a1, ..., a_{L-1}] where p[a_i] = a_{i+1}
            # Let cycle B = [b0, b1, ..., b_{L-1}] where p[b_i] = b_{i+1}
            # We want q such that q[q[a_i]] = a_{i+1} and q[q[b_i]] = b_{i+1}
            # Construction:
            # q[a_i] = b_{(i + L//2) % L}
            # q[b_i] = a_{(i + L//2) % L}
            # Check: q[q[a_i]] = q[b_{(i + L//2) % L}] = a_{((i + L//2) + L//2) % L} = a_{(i + L) % L} = a_{i+1} (mod L logic holds)

            half = L // 2
            for i in range(L):
                u = cycle[i]
                v = other_cycle[(i + half) % L]
                q[u] = v

                x = other_cycle[i]
                y = cycle[(i + half) % L]
                q[x] = y

    # Output result
    result = []
    for i in range(1, n + 1):
        result.append(str(q[i]))
    print(" ".join(result))

